select
    war.*,
    watv.name approveVersionsName
from wms_approve_record war
left join wms_approve_template_versions watv on war.approve_versions_id = watv.id
left join sys_user su on war.applicant_id = su.id and su.bool_delete_enum = 0
left join sys_user su1 on war.last_approver_id = su1.id and su1.bool_delete_enum = 0
left join wms_approve_record_detail ward on war.serial_number = ward.approve_record_serial_number

    war.bool_delete_enum = 0

    AND war.review_status = #{vo.reviewStatus}


    AND war.module_type = #{vo.moduleType}


    AND watv.name LIKE concat('%',#{vo.versionsName},'%')


    AND (
    war.serial_number LIKE concat('%',#{vo.recordSerialNumber},'%')
    OR
    war.source_serial_number LIKE concat('%',#{vo.recordSerialNumber},'%')
    )


    
        
            AND war.create_time >= #{vo.times[0]}
        
        
            AND war.create_time <= #{vo.times[1]}
        
    
    
        
            AND war.last_approval_time >= #{vo.times[0]}
        
        
            AND war.last_approval_time <= #{vo.times[1]}
        
    


    AND war.data_serial_number LIKE concat('%',#{vo.dataSerialNumber},'%')


    AND su.name LIKE concat('%',#{vo.applicant},'%')


    AND su1.name LIKE concat('%',#{vo.lastApprover},'%')


    AND ward.status = 1
    AND ward.check_user_id = #{currentUserId}


    AND war.applicant_id = #{currentUserId}


    AND ward.flow_id IS NOT NULL
    AND ward.approve_time IS NOT NULL
    AND ward.check_user_id = #{currentUserId}


    AND war.component_name IN
    
        #{componentName}
    


    AND war.subjoin_msg LIKE concat('%',#{vo.subjoinMsg},'%')


    AND war.classify_one = #{vo.classifyOne}


    AND war.approve_source = #{vo.approveSource}

    
        AND war.approve_process_type = #{vo.approveProcessType}
    
AND (war.applicant_id = #{currentUserId} or ward.check_user_id = #{currentUserId})

GROUP BY war.id

