select COUNT(*)
from wms_approve_record
where
    bool_delete_enum = 0
  and status = #{status}
  and applicant_id = #{currentUserId}

    and component_name in
    
        #{componentName}

select COUNT(*)
from wms_approve_record
where
    bool_delete_enum = 0
  and status = #{status}
  and review_status = #{reviewStatus}
  and applicant_id = #{currentUserId}
  and last_approval_time >= #{startTime}

